def maybe_request_session(output: Path, request: dict[str, Any]) -> dict[str, Any] | None:
    """Route an ordinary CKB CLI query through an already activated session."""

    if os.environ.get("CKB_STDIO_FALLBACK") == "1":
        return None
    identity = environment_session()
    if identity is None:
        return None
    harness, session_id, parent_pid = identity
    if not _activation_exists(output.resolve(), harness, session_id):
        return None
    return request_session(
        harness=harness,
        session_id=session_id,
        output=output,
        request=request,
        parent_pid=parent_pid,
    )

def list_sessions(*, root: Path | None = None, active_only: bool = False) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    leases: list[dict[str, Any]] = []
    if root_value.is_dir():
        for path in sorted(root_value.glob("stdio-*/lease.json")):
            lease = _read_json(path)
            if not lease:
                continue
            active = lease.get("state") in {"starting", "ready", "closing"} and pid_exists(lease.get("supervisor_pid"))
            if active_only and not active:
                continue
            value = dict(lease)
            value["active"] = active
            leases.append(value)
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed",
        "root": str(root_value),
        "count": len(leases),
        "active": sum(1 for item in leases if item["active"]),
        "leases": leases,
    }

def cleanup_sessions(*, root: Path | None = None, only_key: str | None = None) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    cleaned: list[dict[str, Any]] = []
    if not root_value.is_dir():
        return {"schema_version": SESSION_STDIO_SCHEMA_VERSION, "status": "passed", "root": str(root_value), "cleaned": []}
    directories = [root_value / only_key] if only_key else sorted(path for path in root_value.glob("stdio-*") if path.is_dir())
    for directory in directories:
        lease = _read_json(_lease_path(directory))
        if not lease:
            continue
        supervisor_pid = lease.get("supervisor_pid")
        server_pid = lease.get("server_pid")
        parent_pid = lease.get("parent_pid")
        parent_dead = bool(parent_pid) and not pid_exists(parent_pid)
        supervisor_dead = bool(supervisor_pid) and not pid_exists(supervisor_pid)
        if lease.get("state") in {"starting", "ready", "closing"} and pid_exists(supervisor_pid) and parent_dead:
            json_write(directory / "control" / f"c-{uuid.uuid4().hex[:12]}.json", {"reason": "parent-death-cleanup"})
            cleaned.append({"lifecycle_key": lease.get("lifecycle_key"), "action": "close-requested"})
            continue
        if (supervisor_dead or not supervisor_pid) and lease.get("state") in {"fallback", "closed"}:
            deadline = time.monotonic() + 1.5
            while pid_exists(server_pid) and time.monotonic() < deadline:
                time.sleep(POLL_SECONDS)
            forced = False
            if pid_exists(server_pid):
                forced = _force_terminate_pid(int(server_pid))
            lease.update(
                {
                    "state": "closed",
                    "supervisor_pid": None,
                    "server_pid": None,
                    "closed_at_utc": lease.get("closed_at_utc") or utc_now(),
                    "close_reason": lease.get("close_reason") or "stale-cleanup",
                    "object_counts": _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0),
                }
            )
            _write_lease(directory, lease)
            _clear_transient(directory)
            cleaned.append({"lifecycle_key": lease.get("lifecycle_key"), "action": "stale-cleaned", "forced_server": forced})
    return {"schema_version": SESSION_STDIO_SCHEMA_VERSION, "status": "passed", "root": str(root_value), "cleaned": cleaned}

def audit_sessions(*, root: Path | None = None) -> dict[str, Any]:
    listing = list_sessions(root=root)
    errors: list[str] = []
    totals = _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0)
    for lease in listing["leases"]:
        serialized = json.dumps(lease, ensure_ascii=False, sort_keys=True).casefold()
        for field in _FORBIDDEN_STATE_KEYS:
            if f'"{field}"' in serialized:
                errors.append(f"forbidden-state-field:{field}:{lease.get('lifecycle_key')}")
        counts = lease.get("object_counts") or {}
        if lease.get("active"):
            for name in totals:
                totals[name] += int(counts.get(name, 0))
        elif lease.get("state") == "closed" and any(int(counts.get(name, 0)) for name in totals):
            errors.append(f"closed-object-count:{lease.get('lifecycle_key')}")
        if lease.get("state") == "ready" and not pid_exists(lease.get("server_pid")):
            errors.append(f"ready-server-missing:{lease.get('lifecycle_key')}")
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "root": listing["root"],
        "active": listing["active"],
        "object_counts": totals,
        "errors": errors,
    }

def _parse_sample(value: str) -> tuple[str, Path]:
    if "=" not in value:
        raise CkbError(f"showcase sample must use LABEL=OUTPUT: {value}")
    label, raw = value.split("=", 1)
    label = re.sub(r"[^A-Za-z0-9._-]+", "-", label).strip("-.")
    if not label or not raw.strip():
        raise CkbError(f"showcase sample must use LABEL=OUTPUT: {value}")
    return label, Path(raw).resolve()

class SourceLinkRenderer:
    """Validate one opener config and cache resolved repository paths.

    Retrieval may render several entities from the same file.  The public
    one-shot helpers below intentionally preserve their old behavior, while a
    long-lived renderer avoids repeating Windows ``resolve`` and
    ``_getfinalpathname`` work for every candidate.
    """

    def __init__(self, config: dict[str, Any], *, trusted_relative_paths: bool = False) -> None:
        self.config = validate_local_openers(config)
        root_value = self.config.get("working_repo_root")
        if self.config.get("source_view") == "baseline" and self.config.get("baseline_snapshot_root"):
            root_value = self.config["baseline_snapshot_root"]
        self.root = Path(str(root_value)).resolve()
        self.trusted_relative_paths = trusted_relative_paths
        self._absolute_paths: dict[str, Path] = {}

    @property
    def cache_size(self) -> int:
        return len(self._absolute_paths)

    def absolute_path(self, relative_path: str) -> Path:
        cached = self._absolute_paths.get(relative_path)
        if cached is not None:
            return cached
        relative = PurePosixPath(relative_path)
        if relative.is_absolute() or ".." in relative.parts:
            raise CkbError(f"source path is outside the repository: {relative_path}")
        joined = self.root.joinpath(*relative.parts)
        if self.trusted_relative_paths:
            # Machine retrieval only supplies paths from the audited source
            # manifest.  Absolute and parent components were rejected above,
            # so the lexical path is repository-bounded without another
            # filesystem canonicalization for every selected entity.
            path = joined
        else:
            path = joined.resolve()
            if not path_inside(path, self.root):
                raise CkbError(f"source path is outside the selected source root: {relative_path}")
        self._absolute_paths[relative_path] = path
        return path

    def uri(self, relative_path: str, line: int, column: int = 1) -> str:
        absolute = self.absolute_path(relative_path)
        encoded = quote(absolute.as_posix(), safe="/:")
        editor = self.config["source_editor"]
        if editor == "vscode":
            return f"vscode://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "vscode-insiders":
            return f"vscode-insiders://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "file":
            prefix = "file:///" if os.name == "nt" else "file://"
            return prefix + encoded
        return str(self.config["custom_template"]).format(
            absolute_path=encoded,
            line=int(line),
            column=int(column),
        )

    def markdown_link(self, relative_path: str, start_line: int, end_line: int) -> str:
        uri = self.uri(relative_path, start_line, 1)
        label = f"打开源码：{relative_path} 第 {start_line} 行"
        suffix = f"  `{relative_path}:{start_line}-{end_line}`" if self.config.get("show_source_range", True) else ""
        return f"[{label}]({uri}){suffix}"

